// TestPlaybackUnblockJoint — tv-playback-unblock box 5.1, the Tier-1 joint
// over the change's two cross-group wire contracts, every hop a real
// instance (real store with seeded documents, real api router over real
// HTTP, real stream.Service; no mocks, no scan, no ffmpeg — Describe reads
// stored facts only, so documents are seeded straight through the store).
//
//   - (a) descriptor honesty wire: a store-seeded item document carrying
//     matroska ffprobe facts answers the real GET /items/{id}/playback with
//     mode direct, state preparing, state_reason non_native_container and a
//     live token-carrying direct-floor play_url — the exact served bytes the
//     SPA's 4.2 branch keys on (asserted from the JSON wire, never from
//     internal/api structs); a seeded native-container item in the same
//     harness answers the classic none descriptor with NO state_reason key
//     (the byte-compat guard), and the fetch changed no packaging state.
//   - (b) beacon wire: the EXACT payload the SPA sends on the preparing
//     stall (ItemDetail.tsx: item_id + mode "direct" + phase "stalled" +
//     code "preparing_window_exhausted" + detail) posts through the real
//     router with a real pairing-minted client-role credential to 204 with
//     an empty body, and the entire effect is the one captured INFO line —
//     five fields plus the client User-Agent, never any token material.
//
// Coverage referenced, not re-proven: the honesty projection units
// (stream/describe_honesty_test.go), the beacon verb's shape/rate-limit/
// role-gate units incl. the credential-less 401 (api/playback_events_test.go
// TestPlaybackEvents — 3.1 owns them; not duplicated here), the hls-lane
// end-to-end over scanned media (qa_playback_roundtrip_test.go).
package itest

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/pairing"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
	"github.com/mellifera/mellifera/internal/web"
)

// The SPA's preparing-stall beacon values, verbatim from the sender call
// site (ItemDetail.tsx — the values 4.2/4.3 actually put on the wire), plus
// the world's fixed credentials.
const (
	pubStallCode   = "preparing_window_exhausted"
	pubStallDetail = "the preparing poll window exhausted without a descriptor state change"
	pubStallUA     = "MelliferaTV/1.0 (qa-joint)"
	pubAdminToken  = "qa-tv-unblock-admin-token"
	pubMediaSecret = "qa-tv-unblock-media-secret"
	pubFormatMKV   = "matroska,webm"           // the demuxer's real MKV report
	pubFormatMP4   = "mov,mp4,m4a,3gp,3g2,mj2" // real ffprobe's mp4 report
)

// pubWorld is one composed tv-playback-unblock world: a real store, the real
// stream Service, and the real api+web router over real HTTP. A leaner boot
// than pbNewWorld (the descriptor/beacon wires under test never scan, pack,
// or shell out), but every module boundary it joins is production code, and
// the Deps wiring mirrors cmd/mellifera main.go's Playback + Pairing
// closures in miniature (the shell is package main and cannot be imported —
// the pbNewWorld house pattern).
type pubWorld struct {
	t          *testing.T
	st         *store.Store
	media      *stream.Service
	srv        *httptest.Server
	baseURL    string
	client     *http.Client
	adminToken string
}

// pubNewWorld builds the world. The Playback closure is main.go's
// playbackDescriptor minus the package-main decision log (that line is not a
// wire under this change's joints; keeping it out also keeps the beacon
// capture's buffer free of descriptor noise).
func pubNewWorld(t *testing.T) *pubWorld {
	t.Helper()
	ctx := context.Background()
	tmp := t.TempDir()
	st, err := store.Open(ctx, filepath.Join(tmp, "pub.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })

	media := &stream.Service{
		Root:     filepath.Join(tmp, "streams"),
		Secret:   []byte(pubMediaSecret),
		Original: pbOriginalResolver(st),
	}

	apiH := api.New(api.Deps{
		AdminToken: pubAdminToken,
		Store:      st,
		Pairing:    pairing.NewService(st, nil),
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			row, err := st.GetItem(ctx, itemID)
			if err != nil {
				return api.Playback{}, err
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return api.Playback{}, err
			}
			mode, state, playURL, sections, voiceovers, stateReason := media.Describe(itemID, doc)
			tok, _ := media.Issue(itemID, time.Now())
			return api.Playback{Mode: mode, State: state, PlayURL: playURL, StateReason: stateReason, Sections: sections, Voiceovers: voiceovers, Token: tok}, nil
		},
	})
	srv := httptest.NewServer(web.Handler(apiH, web.Options{Media: media}))
	t.Cleanup(srv.Close)
	return &pubWorld{
		t: t, st: st, media: media, srv: srv,
		baseURL:    srv.URL,
		client:     &http.Client{Timeout: 30 * time.Second},
		adminToken: pubAdminToken,
	}
}

// pubDescriptor is the descriptor wire shape decoded from the SERVED bytes —
// state_reason and the two arrays stay raw so the test asserts the wire's
// presence/absence and array-ness exactly as the SPA consumes them (a typed
// slice would silently accept a JSON null; an empty Go string would hide a
// missing key).
type pubDescriptor struct {
	Mode        string          `json:"mode"`
	State       string          `json:"state"`
	PlayURL     string          `json:"play_url"`
	StateReason json.RawMessage `json:"state_reason"`
	Sections    json.RawMessage `json:"sections"`
	Voiceovers  json.RawMessage `json:"voiceovers"`
}

// pubSeedItem writes one real floor file and puts one item row directly
// through the store, its document carrying ffprobe facts shaped like the
// roundtrip fixture's (format.format_name + an h264/aac stream pair — the
// canonical packable shape) with the streams namespace parked at none. The
// id mirrors scan/run.go's itemID scheme; the row needs no scan, no plugin,
// no ffmpeg.
func pubSeedItem(t *testing.T, w *pubWorld, libID int64, rel, formatName string) string {
	t.Helper()
	ctx := context.Background()
	floor := filepath.Join(t.TempDir(), filepath.Base(rel))
	if err := os.WriteFile(floor, []byte("floor bytes of "+rel), 0o644); err != nil {
		t.Fatalf("write floor fixture: %v", err)
	}
	doc := map[string]any{
		"parsed": map[string]any{"absolute_path": floor},
		"ffprobe": map[string]any{
			"format": map[string]any{"format_name": formatName, "duration": "5.000000"},
			"streams": []any{
				map[string]any{"codec_name": "h264", "codec_type": "video", "pix_fmt": "yuv420p", "width": 128, "height": 72},
				map[string]any{"codec_name": "aac", "codec_type": "audio", "sample_rate": "44100"},
			},
		},
		"streams": map[string]any{"state": stream.StateNone},
	}
	raw, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal doc: %v", err)
	}
	fileID := fmt.Sprintf("pub%d-%s", libID, strings.ReplaceAll(rel, "/", "_"))
	itemID := fmt.Sprintf("itm_%d_%s", libID, fileID)
	err = w.st.PutItem(ctx, store.Item{
		ID: itemID, ModuleID: "base", LibraryID: libID, FileID: fileID,
		RelativePath: rel, MediaType: "movie", Document: raw, SchemaVersion: 1,
	})
	if err != nil {
		t.Fatalf("seed item %s: %v", rel, err)
	}
	return itemID
}

// pubMintClientToken pairs one device through the REAL router flow (create →
// admin approve → wait) and returns the minted RoleClient credential — the
// TV's voice on the browse surface, the api package's mintClientToken
// pattern driven over HTTP instead of the handler directly.
func pubMintClientToken(t *testing.T, w *pubWorld) string {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodPost, w.baseURL+"/api/v1/pair", "", nil)
	if status != http.StatusOK {
		t.Fatalf("pair create: status %d (body=%s)", status, body)
	}
	var created struct {
		PairingID string `json:"pairing_id"`
	}
	if err := json.Unmarshal(body, &created); err != nil || created.PairingID == "" {
		t.Fatalf("decode pair create: %v (%s)", err, body)
	}
	approveURL := w.baseURL + "/api/v1/admin/pairings/" + created.PairingID + "/approve"
	if status, body, _ = pbDo(t, w.client, http.MethodPost, approveURL, w.adminToken, nil); status != http.StatusOK {
		t.Fatalf("pair approve: status %d (body=%s)", status, body)
	}
	status, body, _ = pbDo(t, w.client, http.MethodGet, w.baseURL+"/api/v1/pair/"+created.PairingID+"/wait", "", nil)
	if status != http.StatusOK {
		t.Fatalf("pair wait: status %d (body=%s)", status, body)
	}
	var waited struct {
		DeviceToken string `json:"device_token"`
	}
	if err := json.Unmarshal(body, &waited); err != nil || waited.DeviceToken == "" {
		t.Fatalf("decode pair wait: %v (%s)", err, body)
	}
	return waited.DeviceToken
}

// pubFetchDescriptor fetches the descriptor with the given bearer (the TV
// uses its client-role credential) and returns the served bytes plus their
// wire decode, failing on any non-200.
func pubFetchDescriptor(t *testing.T, w *pubWorld, bearer, itemID string) ([]byte, pubDescriptor) {
	t.Helper()
	status, body, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+"/api/v1/items/"+itemID+"/playback", bearer, nil)
	if status != http.StatusOK {
		t.Fatalf("descriptor %s: status %d, want 200 (body=%s)", itemID, status, body)
	}
	var pb pubDescriptor
	if err := json.Unmarshal(body, &pb); err != nil {
		t.Fatalf("decode descriptor %s: %v (body=%s)", itemID, err, body)
	}
	return body, pb
}

// pubPostBeacon posts one beacon payload with the given bearer and
// User-Agent through the real router (pbDo cannot carry a UA) and returns
// status + body bytes.
func pubPostBeacon(t *testing.T, w *pubWorld, bearer string, payload map[string]string, ua string) (int, []byte) {
	t.Helper()
	buf := new(bytes.Buffer)
	if err := json.NewEncoder(buf).Encode(payload); err != nil {
		t.Fatalf("encode beacon payload: %v", err)
	}
	req, err := http.NewRequest(http.MethodPost, w.baseURL+"/api/v1/playback-events", buf)
	if err != nil {
		t.Fatalf("new beacon request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", ua)
	if bearer != "" {
		req.Header.Set("Authorization", "Bearer "+bearer)
	}
	resp, err := w.client.Do(req)
	if err != nil {
		t.Fatalf("post beacon: %v", err)
	}
	defer resp.Body.Close()
	out, rerr := io.ReadAll(resp.Body)
	if rerr != nil {
		t.Fatalf("read beacon body: %v", rerr)
	}
	return resp.StatusCode, out
}

// pubCaptureLogs swaps the default slog logger for one writing to the
// returned buffer and restores it on cleanup (the api package's captureLogs
// precedent, mirrored because that helper is package-internal).
func pubCaptureLogs(t *testing.T) *strings.Builder {
	t.Helper()
	var buf strings.Builder
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })
	return &buf
}

// pubBeaconLines returns the captured lines carrying the beacon message
// (the request-log middleware's own INFO lines share the buffer and are
// filtered out).
func pubBeaconLines(buf *strings.Builder) []string {
	var lines []string
	for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
		if strings.Contains(ln, `msg="playback event"`) {
			lines = append(lines, ln)
		}
	}
	return lines
}

// pubStoredStreamsState reads the persisted streams namespace back from the
// store (the fetch-changed-nothing guard reads reality, not the wire).
func pubStoredStreamsState(t *testing.T, w *pubWorld, itemID string) string {
	t.Helper()
	row, err := w.st.GetItem(context.Background(), itemID)
	if err != nil {
		t.Fatalf("re-read item %s: %v", itemID, err)
	}
	var doc struct {
		Streams struct {
			State string `json:"state"`
		} `json:"streams"`
	}
	if err := json.Unmarshal(row.Document, &doc); err != nil {
		t.Fatalf("re-read doc %s: %v", itemID, err)
	}
	return doc.Streams.State
}

// TestPlaybackUnblockJoint is 5.1's acceptance floor: both cross-group wire
// contracts hold over real instances.
func TestPlaybackUnblockJoint(t *testing.T) {
	w := pubNewWorld(t)
	ctx := context.Background()

	libID, err := w.st.CreateLibrary(ctx, "base", t.TempDir(), "QA TV Unblock")
	if err != nil {
		t.Fatalf("create library: %v", err)
	}
	mkvID := pubSeedItem(t, w, libID, "tv-unblock/Matroska-Movie-QA.mkv", pubFormatMKV)
	mp4ID := pubSeedItem(t, w, libID, "tv-unblock/Native-Movie-QA.mp4", pubFormatMP4)

	// The TV's real credential, minted through the real pairing flow — the
	// same bearer the descriptor GET and the beacon POST ride below.
	clientTok := pubMintClientToken(t, w)

	// --- (a) descriptor honesty wire ------------------------------------
	// The matroska item answers the honesty projection through the REAL api
	// handler: mode direct, state preparing, state_reason
	// non_native_container, the direct floor's play_url still present — the
	// exact shape the SPA's 4.2 branch keys on (packaged-playback delta
	// scenario "Non-native container answers preparing with a reason").
	mkvBody, mkv := pubFetchDescriptor(t, w, clientTok, mkvID)
	if mkv.Mode != "direct" || mkv.State != "preparing" {
		t.Fatalf("matroska descriptor = mode %q state %q, want direct/preparing", mkv.Mode, mkv.State)
	}
	if !strings.Contains(string(mkvBody), `"state_reason"`) {
		t.Fatalf("matroska descriptor body carries no state_reason key: %s", mkvBody)
	}
	if string(mkv.StateReason) != `"non_native_container"` {
		t.Fatalf("state_reason = %s, want non_native_container", mkv.StateReason)
	}
	if !strings.HasPrefix(mkv.PlayURL, "/media/"+mkvID+"/original?token=") || strings.HasSuffix(mkv.PlayURL, "token=") {
		t.Fatalf("matroska play_url = %q, want the direct floor with a token", mkv.PlayURL)
	}
	// The two arrays ride the wire as arrays even when empty — the SPA reads
	// .length unguarded (the vipDescriptor house assertion, from the bytes).
	if sections := vipArray(t, mkv.Sections, "sections"); len(sections) != 0 {
		t.Fatalf("sections = %v, want the empty projection (no chapters seeded)", sections)
	}
	if voiceovers := vipArray(t, mkv.Voiceovers, "voiceovers"); len(voiceovers) != 0 {
		t.Fatalf("voiceovers = %v, want the empty projection (no sidecars seeded)", voiceovers)
	}
	// The floor is live: the play_url's token opens the original through the
	// real media mount, byte-for-byte the seeded fixture.
	floorStatus, floorBody, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+mkv.PlayURL, "", nil)
	if floorStatus != http.StatusOK || !strings.Contains(string(floorBody), "floor bytes of tv-unblock/Matroska-Movie-QA.mkv") {
		t.Fatalf("matroska floor %s: status %d body %q, want 200 with the seeded bytes", mkv.PlayURL, floorStatus, floorBody)
	}
	// The fetch changed no packaging state: the persisted namespace still
	// sits at none — preparing is a read-side projection, never stored.
	if got := pubStoredStreamsState(t, w, mkvID); got != stream.StateNone {
		t.Fatalf("persisted streams state after descriptor GET = %q, want %q (the honesty projection never writes)", got, stream.StateNone)
	}

	// The byte-compat guard: a native-container item with the same codecs
	// keeps the classic descriptor — state none, NO state_reason key on the
	// wire (packaged-playback delta scenario "Native container keeps the
	// classic descriptor").
	mp4Body, mp4 := pubFetchDescriptor(t, w, clientTok, mp4ID)
	if mp4.Mode != "direct" || mp4.State != stream.StateNone {
		t.Fatalf("native descriptor = mode %q state %q, want direct/none", mp4.Mode, mp4.State)
	}
	if strings.Contains(string(mp4Body), "state_reason") {
		t.Fatalf("native descriptor body carries a state_reason key (byte-compat break): %s", mp4Body)
	}
	if mp4.PlayURL == "" {
		t.Fatal("native descriptor carries no play_url")
	}

	// --- (b) beacon wire --------------------------------------------------
	// The EXACT SPA payload (five fields, the stalled-edge values the SPA
	// sends per 4.2/4.3) posts through the real router with the TV's
	// client-role credential and a TV User-Agent, answers 204 with an empty
	// body, and its ENTIRE effect is the one captured INFO line (packaged-
	// playback delta scenario "Beacon accepted and logged"). The verb's
	// shape/rate-limit/role-gate units — including the credential-less 401 —
	// are 3.1's TestPlaybackEvents and are referenced, not duplicated.
	buf := pubCaptureLogs(t)
	payload := map[string]string{
		"item_id": mkvID,
		"mode":    "direct",
		"phase":   "stalled",
		"code":    pubStallCode,
		"detail":  pubStallDetail,
	}
	status, body := pubPostBeacon(t, w, clientTok, payload, pubStallUA)
	if status != http.StatusNoContent {
		t.Fatalf("beacon status = %d, want 204 (body=%s)", status, body)
	}
	if len(body) != 0 {
		t.Fatalf("204 carried a body: %q", body)
	}
	lines := pubBeaconLines(buf)
	if len(lines) != 1 {
		t.Fatalf("captured %d beacon lines, want exactly 1; output:\n%s", len(lines), buf.String())
	}
	for _, field := range []string{
		"item=" + mkvID,
		"mode=direct",
		"phase=stalled",
		"code=" + pubStallCode,
		`detail="` + pubStallDetail + `"`, // the text handler quotes spaced values
		`ua="` + pubStallUA + `"`,
	} {
		if !strings.Contains(lines[0], field) {
			t.Fatalf("beacon line %q lacks %q", lines[0], field)
		}
	}
	// INV4: no credential or media-token material anywhere in the capture —
	// the device token, the admin bearer, and the descriptor's fresh play
	// token all rode this session and none may surface.
	playToken := mkv.PlayURL[strings.Index(mkv.PlayURL, "token=")+len("token="):]
	for _, secret := range []string{clientTok, w.adminToken, playToken, "media_token"} {
		if strings.Contains(buf.String(), secret) {
			t.Fatalf("captured log carries token material %q (INV4):\n%s", secret, buf.String())
		}
	}
}
